import { useEffect, useRef, useState } from "react";
import { extractErrorMessage } from "../api/axios";

export function useLookupOptions(fetchFn, mapper) {
  const [options, setOptions] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");

  const fetchFnRef = useRef(fetchFn);
  const mapperRef = useRef(mapper);

  useEffect(() => {
    fetchFnRef.current = fetchFn;
  }, [fetchFn]);

  useEffect(() => {
    mapperRef.current = mapper;
  }, [mapper]);

  useEffect(() => {
    let isCurrent = true;

    async function loadOptions() {
      setIsLoading(true);
      setError("");

      try {
        const response = await fetchFnRef.current();
        const responseData = response?.data;

        if (!isCurrent) return;

        console.log("Lookup API response:", responseData);

        let list = [];

        /*
         * Supported backend response formats
         */

        // [ ... ]
        if (Array.isArray(responseData)) {
          list = responseData;
        }

        // { data: [...] }
        else if (Array.isArray(responseData?.data)) {
          list = responseData.data;
        }

        // { data: { students: [...] } }
        else if (Array.isArray(responseData?.data?.students)) {
          list = responseData.data.students;
        }

        // { data: { courses: [...] } }
        else if (Array.isArray(responseData?.data?.courses)) {
          list = responseData.data.courses;
        }

        // { data: { departments: [...] } }
        else if (Array.isArray(responseData?.data?.departments)) {
          list = responseData.data.departments;
        }

        // { data: { items: [...] } }
        else if (Array.isArray(responseData?.data?.items)) {
          list = responseData.data.items;
        }

        // { students: [...] }
        else if (Array.isArray(responseData?.students)) {
          list = responseData.students;
        }

        // { courses: [...] }
        else if (Array.isArray(responseData?.courses)) {
          list = responseData.courses;
        }

        // { departments: [...] }
        else if (Array.isArray(responseData?.departments)) {
          list = responseData.departments;
        }

        // { items: [...] }
        else if (Array.isArray(responseData?.items)) {
          list = responseData.items;
        }

        console.log("Lookup list:", list);

        const mappedOptions = list
          .map((item) => {
            try {
              return mapperRef.current(item);
            } catch (mapperError) {
              console.error(
                "Lookup mapper error:",
                mapperError
              );
              return null;
            }
          })
          .filter(
            (option) =>
              option &&
              option.value !== undefined &&
              option.value !== null &&
              option.value !== ""
          );

        console.log(
          "Mapped lookup options:",
          mappedOptions
        );

        if (isCurrent) {
          setOptions(mappedOptions);
        }
      } catch (err) {
        if (!isCurrent) return;

        console.error("Lookup API error:", err);

        setOptions([]);

        setError(
          extractErrorMessage(
            err,
            "Unable to load options."
          )
        );
      } finally {
        if (isCurrent) {
          setIsLoading(false);
        }
      }
    }

    loadOptions();

    return () => {
      isCurrent = false;
    };
  }, []);

  return {
    options,
    isLoading,
    error
  };
}
